{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Intravenous administration of S-(7-[11C]methylpurin-6-yl)glutathione in mice produced extremely low brain radioactivity (<1% ID/mL for 60 min), directly demonstrating impermeable BBB access for a high-transfer analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In mice, [11C]AZ10419369 had low baseline brain uptake that increased 207% after cyclosporin A, showing ABC-transporter-limited BBB penetration; this efflux liability is transferable to the query's large heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Compound 7z was undetectable in brain tissue (LLOQ = 10 ng/mL) after in vivo dosing, indicating failure to cross the BBB despite a moderately sized heteroaromatic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "[18F]cabozantinib showed negligible brain uptake in mice, demonstrating that even a molecule with brain-tumor treatment responses can lack meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "CGP74588, an active imatinib metabolite, had low brain uptake restricted by Bcrp1, supporting efflux-mediated poor CNS exposure for heteroaromatic amide-containing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The methoxy analogue 17 had a brain-to-plasma ratio of 0.19 attributed to high P-gp efflux, directly quantifying poor brain penetration in a structurally related amide-containing compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "In two human subjects, [11C]AZ10419369 showed rapid brain distribution with 3-4% of injected radioactivity, providing a contradictory example where rodent efflux did not preclude human CNS access; however, the query's much higher molecular weight and polar surface area reduce transferability of this favorable human result.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is predicted to lack meaningful CNS access. Multiple high-transfer experimental analogues show impermeable BBB behavior, very low brain uptake, or efflux-limited brain penetration, and the query's very high molecular weight, TPSA, and HBA count are consistent with poor passive diffusion and likely transporter-mediated exclusion. One contradictory human dataset for a smaller analogue does not overcome the consistent fail-direction evidence.",
  "evidence_gaps": [
    "No direct experimental brain, CSF, or plasma exposure data for the query molecule itself.",
    "No human PET or pharmacokinetic data for a close structural analogue of the query.",
    "The specific efflux transporter phenotype (P-gp, BCRP, etc.) of the query has not been directly measured.",
    "No Kp,uu or CSF-to-plasma ratio is available to quantify unbound brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

